//! 🧪️ Portable cubic, quadratic and endpoint-arc samples match independent Three-produced positions.
use super::*;
#[test]fn curved_projection_matches_independent_physical_witnesses(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️curves.json")).unwrap();let point=|v:&serde_json::Value|[v[0].as_f64().unwrap(),v[1].as_f64().unwrap()];for row in fixture["cases"].as_array().unwrap(){let p=point(&row["start"]);let to=point(&row["to"]);let actual=match row["kind"].as_str().unwrap(){"cubic"=>cubic_points(p,point(&row["c1"]),point(&row["c2"]),to).to_vec(),"quad"=>quad_points(p,point(&row["control"]),to).to_vec(),_=>arc_points(p,to,[row["rx"].as_f64().unwrap(),row["ry"].as_f64().unwrap()],row["xRotation"].as_f64().unwrap(),row["largeArc"].as_bool().unwrap(),row["sweep"].as_bool().unwrap()).unwrap()};let expected=row["expected"].as_array().unwrap();assert_eq!(actual.len(),expected.len());for(actual,expected)in actual.iter().zip(expected){for axis in 0..2{assert!((actual[axis]-expected[axis].as_f64().unwrap()).abs()<1e-9);}}}}
